<div class="ff-studio" :class="{'ff-preview-mode':previewMode}" data-initial="{{ json_encode($this->initialState(), JSON_UNESCAPED_UNICODE) }}" x-data="filaforgeEditor(JSON.parse($el.dataset.initial), $wire)" x-on:beforeunload.window="if(dirty){$event.preventDefault();$event.returnValue='';}" x-on:keydown.window="shortcut($event)">
<header class="ff-bar">
